    <div class="score-row">
      <span class="score-label">Season Fit</span>
      <div class="score-bar-bg"><div class="score-bar bar-green" style="width:81%"></div></div>
      <span class="score-val">81%</span>
    </div>
    <div class="score-row">
      <span class="score-label">Occasion Match</span>
      <div class="score-bar-bg"><div class="score-bar bar-amber" style="width:58%"></div></div>
      <span class="score-val">58%</span>
    </div>
    <div class="score-row">
      <span class="score-label">User Satisfaction</span>
      <div class="score-bar-bg"><div class="score-bar bar-rose" style="width:74%"></div></div>
      <span class="score-val">74%</span>
    </div>
  </div>

